const cityPhotos={"Paris": "1502602898657-3e91760cbb34", "Interlaken": "1656184554687-016511d620eb", "Rome": "1552832230-c0197dd311b5", "Amsterdam": "1534351590666-13e3e96b5017", "Venice": "1514890547357-a9ee288728e0", "Barcelona": "1539037116277-4db20889f2d4", "Tokyo": "1540959733332-eab4deabeeaf", "Bali": "1537996194471-e657df975ab4", "London": "1513635269975-59663e0ac1ad", "Lisbon": "1555881400-74d7acaacd8b"};
const moodPhotos={Mountains:['assets/mountains-impasto.png','Impasto painting of sunlit alpine peaks and a turquoise lake'],Beaches:['assets/beaches-seascape.png','Painted seascape with pink clouds, blue waves and a rocky shoreline'],Architecture:['assets/architecture-roman-ruins.png','Painted Roman ruins and the Colosseum beneath pink clouds at golden hour'],'New year escapes':['assets/new-year-impasto.png','Impasto painting of golden fireworks above a festive waterfront city']};function moodPhoto(m){const [id,alt]=moodPhotos[m];return `<img src="${id.startsWith('assets/')?id:'https://images.unsplash.com/'+id+'?auto=format&fit=crop&w=560&q=85'}" alt="${alt}" width="156" height="204"><span class="mood-label">${m}</span>`}
const $=s=>document.querySelector(s);const params=new URLSearchParams(location.search);let screen=params.get('screen')||'home',mood='Mountains';let state;try{state=JSON.parse(localStorage.getItem('away-trip'))}catch{}state=state||{cities:[],start:'',end:'',pace:'Balanced',activities:{},saved:false};const cities=[['Paris','France','♜'],['Interlaken','Switzerland','△'],['Rome','Italy','♜'],['Amsterdam','Netherlands','⌂'],['Venice','Italy','≈'],['Barcelona','Spain','☀'],['Tokyo','Japan','♜'],['Bali','Indonesia','≈'],['London','United Kingdom','⌂'],['Lisbon','Portugal','☀']];const moods=[['Mountains','△','green'],['Beaches','≈','teal'],['Architecture','♜','red'],['New year escapes','✳','blue']];const names={home:'Explore',destinations:'Destinations',dates:'Dates',trip:'Your trip',inspiration:'Inspiration',saved:'Saved trips',planning:'Plan each city'};function persist(){localStorage.setItem('away-trip',JSON.stringify(state))}function go(s){screen=s;const u=new URL(location);u.searchParams.set('screen',s);history.pushState({},'',u);render()}window.onpopstate=()=>{screen=new URLSearchParams(location.search).get('screen')||'home';render()};function header(title,back){return `<header>${back?`<button class="back" data-go="${back}" aria-label="Go back"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></button>`:'<span aria-hidden="true"></span>'}<span>${title||''}</span>${back?'':'<span class="avatar">A</span>'}</header>`}function nav(){return ''}function footer(label,action,disabled=false){return `<div class="footer"><button class="primary" data-action="${action}" ${disabled?'disabled':''}>${label}</button></div>`}function stamp(label,symbol,color='blue'){return `<div class="stamp ${color}"><div class="stamp-inner"><small>YOUR NEXT CHAPTER</small><strong>${symbol}</strong><b>${label}</b><small>ADMIT ONE · GO SOMEWHERE</small></div></div>`}function render(){document.body.classList.toggle('embed',params.get('embed')==='1'||$('#embed').checked);$('#screen-links').innerHTML=Object.entries(names).map(([k,v])=>`<button data-go="${k}" class="${screen===k?'active':''}">${v}</button>`).join('');let html='';if(screen==='home'){html=header()+`<div class="content"><div class="home-heading"><h2>Where to,<br>Aditi?</h2><button class="primary home-create" data-go="destinations"><svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-plus" aria-hidden="true"><path d="M5 12h14"/><path d="M12 5v14"/></svg><span>Create a trip</span></button></div>${homeTripCard()}<div class="section-head"><h3>Explore by interest</h3></div><div class="rail">${moods.map(([m,s,c])=>`<button class="mood" data-mood="${m}">${moodPhoto(m)}</button>`).join('')}</div><section class="new-year-section"><h3>A new year, somewhere new</h3><div class="rail city-rail" aria-label="New Year city ideas">${newYearCities.map(([city,photo,alt,vibe])=>`<button class="new-year-card" data-pick="${city}"><img src="${photo.startsWith('assets/')?photo:'https://images.unsplash.com/'+photo+'?auto=format&fit=crop&w=640&q=85'}" alt="${alt}" width="220" height="150" loading="lazy"><span class="city-name">${city}</span><span class="city-vibe">${vibe}</span></button>`).join('')}</div></section></div>`+nav()}else if(screen==='destinations'){html=routeMap()+header('', 'home')+`<div class="content destination-content"><h2>Where are<br>you heading?</h2><input class="search" id="search" placeholder="Search cities or countries" aria-label="Search cities or countries"><div class="cities">${cityList('')}</div></div>`+footer(state.cities.length?`Choose dates · ${state.cities.length} ${state.cities.length===1?'stop':'stops'}`:'Choose a place to continue','dates',!state.cities.length)}else if(screen==='dates'){html=header('','destinations')+`<div class="content"><h2>Choose dates</h2>${calendarPicker()}<p id="date-error" role="alert" class="muted"></p></div>`+footer('Put my trip together','build')}else if(screen==='planning'){html=cityPlanning()}else if(screen==='trip'){html=tripCityList()}else if(screen==='inspiration'){const options=mood==='Mountains'?['Interlaken']:mood==='Beaches'?['Bali']:mood==='Architecture'?['Paris','Rome','Barcelona']:['Tokyo','Amsterdam'];html=header('','home')+`<div class="content"><p class="eyebrow">EXPLORE BY INTEREST</p><h2>${mood}</h2><p class="muted">Somewhere that feels like you.</p>${options.map((c,i)=>`<section class="inspo">${stamp(c,cities.find(x=>x[0]===c)[2],['green','red','teal'][i%3])}<div><h3>${c}</h3><p class="muted">${mood==='Mountains'?'Alpine views and unhurried days.':mood==='Beaches'?'Salty air and a slower rhythm.':'A different view around every corner.'}</p><button class="linkbtn" data-pick="${c}">Plan a trip here</button></div></section>`).join('')}<p class="muted">Editorial demo ideas, not live recommendations.</p></div>`+nav()}else{html=header()+`<div class="content"><p class="eyebrow">THE CHAPTERS AHEAD</p><h2>My trips</h2>${state.saved?`<section class="saved">${stamp(state.cities[0]||'Away','✳','green')}<h3>${state.title||'Europe 2026'}</h3><p class="muted">${state.start} · Saved on this device</p><button class="primary" data-go="trip">Open trip</button></section>`:`<div class="note">Your next story is waiting. Create a trip and save it here.</div><button class="primary" data-go="destinations">Create a trip</button>`}</div>`+nav()}$('.phone').classList.toggle('figma-planning-phone',['planning','trip'].includes(screen));$('.phone').classList.toggle('has-route-map',screen==='destinations');$('#app').classList.toggle('no-bottom-nav',['home','inspiration','saved','trip'].includes(screen));$('#app').innerHTML=html;$('#app').scrollTop=0;persist()}
function cityList(q){const filtered=cities.filter(c=>c.slice(0,2).join(' ').toLowerCase().includes(q.toLowerCase()));return filtered.map(([c,country,icon])=>`<button class="city ${state.cities.includes(c)?'checked':''}" data-city="${c}" aria-pressed="${state.cities.includes(c)}"><img class="city-photo" src="https://images.unsplash.com/photo-${cityPhotos[c]}?auto=format&fit=crop&w=160&h=160&q=85" alt="${c}" width="56" height="56"><span><b>${c}</b><small>${country}</small></span></button>`).join('')||'<p class="muted">No matching cities in this demo.</p>'}document.addEventListener('input',e=>{if(e.target.id==='search')$('.cities').innerHTML=cityList(e.target.value);if(['start','end'].includes(e.target.id)){state[e.target.id]=e.target.value;if(e.target.id==='start')$('#end').min=e.target.value;persist()}});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.go)go(d.go);if(d.city){const scroll=$('.destination-content')?.scrollTop||0;const query=$('#search')?.value||'';state.cities=state.cities.includes(d.city)?state.cities.filter(c=>c!==d.city):[...state.cities,d.city];render();if(screen==='destinations'){$('#search').value=query;$('.cities').innerHTML=cityList(query);$('.destination-content').scrollTop=scroll}}if(d.mood){mood=d.mood;go('inspiration')}if(d.pick){state.cities=[d.pick];go('destinations')}if(d.pace){state.pace=d.pace;render()}if(d.suggestion){const scroll=$('#app').scrollTop;const c=state.cities[state.planningIndex||0];state.activities??={};state.activities[c]??=[];const a=d.suggestion;state.activities[c]=state.activities[c].includes(a)?state.activities[c].filter(x=>x!==a):[...state.activities[c],a];render();$('#app').scrollTop=scroll;document.querySelector(`[data-suggestion="${a}"]`)?.focus({preventScroll:true})}if(d.action==='next-city'){const range=state.cityDates?.[state.cities[state.planningIndex||0]];if(!cityEndSelected(range))return;if((state.planningIndex||0)<state.cities.length-1){transitionCity((state.planningIndex||0)+1)}else{state.saved=true;go('trip')}}if(d.action==='previous-city'){if(state.planningIndex>0){transitionCity(state.planningIndex-1)}else go('dates')}if(d.editCity!==undefined){state.planningIndex=Number(d.editCity);go('planning')}if(d.action==='dates')go('dates');if(d.action==='build'){if(!state.cities.length){go('destinations');return}if(!state.start||!state.end||state.end<state.start){$('#date-error').textContent='Choose a departure and a return date after it.';return}state.title='Europe 2026';state.planningIndex=0;prepareCityPlans();persist();go('planning')}if(d.action==='save'){state.saved=true;persist();go('saved')}if(d.add){state.activities[d.add]??=[];const suggestions=['A local food walk','A quiet morning at a café','Explore a local museum','An afternoon at the market'];const next=suggestions.find(a=>!state.activities[d.add].includes(a));if(next)state.activities[d.add].push(next);render()}if(d.remove){const [c,j]=d.remove.split('|');state.activities[c].splice(+j,1);render()}});$('#embed').checked=params.get('embed')==='1';$('#embed').onchange=()=>render();$('#copy').onclick=async()=>{const u=new URL(location);u.searchParams.set('embed','1');try{await navigator.clipboard.writeText(`<iframe src="${u}" title="Away travel prototype" width="390" height="844" style="border:0;border-radius:24px" loading="lazy"></iframe>`);$('#copied').textContent='Embed code copied'}catch{$('#copied').textContent='Use ?embed=1&screen='+screen+' in your iframe URL'}};

const cityIdeas={Paris:['Walk along the Seine','Explore the Louvre','Spend a morning in Montmartre','Find a neighbourhood pâtisserie'],Interlaken:['Walk beside Lake Brienz','Explore the old town','Take in the Alpine views'],Rome:['Explore the Roman Forum','Wander through Trastevere','Visit the Vatican Museums'],Amsterdam:['Walk the canal ring','Explore the Rijksmuseum','Browse the Jordaan'],Venice:['Explore the canals','Visit the Doge’s Palace','Wander through Cannaregio'],Barcelona:['Explore Park Güell','Visit the Sagrada Família','Walk the Gothic Quarter'],Tokyo:['Explore Asakusa','Browse the shops in Shibuya','Visit a neighbourhood ramen bar'],Bali:['Explore Ubud','Spend an afternoon by the sea','Visit the rice terraces'],London:['Explore the British Museum','Walk along the South Bank','Browse Borough Market'],Lisbon:['Wander through Alfama','Visit Belém','Watch the sunset from a miradouro']};
function cityEndSelected(range){return !!range?.end&&range.endChosen===range.end&&range.end>=range.start&&range.end<=state.end}
function prepareCityPlans(){
 state.activities??={};state.cityDates??={};for(const c of state.cities){state.activities[c]=(state.activities[c]||[]).filter(a=>!['Settle in & explore the neighbourhood','Leave a little room to wander'].includes(a))}
 const key=[state.start,state.end,...state.cities].join('|');
 if(state.cityDatesKey===key){for(const c of state.cities){const r=state.cityDates[c];if(r&&!r.endChosen)r.end=''}return;}
 const total=Math.round((parseDay(state.end)-parseDay(state.start))/86400000)+1;
 state.cities.forEach((c,i)=>{const offset=Math.min(total-1,Math.floor(total*i/state.cities.length));const endOffset=Math.max(offset,Math.min(total-1,Math.floor(total*(i+1)/state.cities.length)-1));const a=parseDay(state.start),b=parseDay(state.start);a.setDate(a.getDate()+offset);b.setDate(b.getDate()+endOffset);state.cityDates[c]={start:localDate(a),end:''};state.activities[c]??=[]});
 state.cityDatesKey=key;
}
function cityPlanning(){
 if(!state.cities.length||!state.start||!state.end)return header('','dates')+'<div class="content"><h2>Choose your cities and dates</h2><button class="primary" data-go="destinations">Plan a trip</button></div>';
 prepareCityPlans();const i=Math.min(state.planningIndex||0,state.cities.length-1),c=state.cities[i];state.planningIndex=i;const range=state.cityDates[c];
 const photo=cityCoverPhoto(c);
 return `<div class="content city-planning figma-planning"><div class="figma-trip-heading"><h2>${state.title||'Europe 2026'}</h2><p class="planning-trip-dates">${dateLabel(state.start)} – ${dateLabel(state.end)}</p><button class="figma-close" data-go="home" aria-label="Close trip"><img src="assets/figma/close.svg" alt=""></button></div>${planningRoute(i)}<div class="planning-cover"><img src="${photo}" alt="${c}"><h1>${c}</h1></div>${cityDateRow(c,range)}${cityArticle(c)}</div><div class="footer planning-footer"><button class="planning-back" data-action="previous-city" aria-label="${i?'Previous city':'Back to dates'}">${chevron()}</button><button class="primary" data-action="next-city" ${!cityEndSelected(range)?'disabled':''}>Next</button></div>`;

}
function cityDateRow(c,range){
 let days='';for(let d=parseDay(state.start),last=parseDay(state.end);d<=last;d.setDate(d.getDate()+1)){const iso=localDate(d),edge=iso===range.start||iso===range.end,inside=!!range.end&&iso>=range.start&&iso<=range.end;
 days+=`<button class="city-date ${edge?'endpoint':''} ${iso===range.start?'arrival':''} ${inside?'in-range':''}" data-planning-day="${iso}" ${iso<range.start?'disabled':''} aria-pressed="${edge||inside}" aria-label="${dateLabel(iso)}${iso===range.start?', arrival':''}${iso===range.end?', departure':''}"><small>${d.toLocaleDateString('en-GB',{weekday:'short'})}</small><strong>${d.getDate()}</strong><small>${d.toLocaleDateString('en-GB',{month:'short'})}</small></button>`}
 return `<section class="city-date-picker" aria-label="Choose dates in ${c}"><h3 class="date-rail-heading">Select dates</h3><div class="city-date-row">${days}</div></section>`;
}
function cityInsight(c,range){
 const month=parseDay(range.start).getMonth()+1,win=month>=11||month<=2;
 const length=range.end?Math.round((parseDay(range.end)-parseDay(range.start))/86400000)+1:1;
 let text=win?'Plan outdoor stops in daylight and keep an indoor option for later.':'Choose one main sight each day, then leave room to explore the neighbourhood around it.';
 let source='';
 if(c==='Paris'&&win){text='Pair a museum afternoon with a daytime Seine walk and a cosy café stop. A flexible mix of indoor and outdoor plans suits this time of year.';source='https://parisjetaime.com/eng/article/what-to-do-in-paris-in-winter-a1819'}
 if(c==='Amsterdam'&&win){text='Winter is usually quieter at the major museums. Combine the Rijksmuseum with a short canal walk and a warm café stop.';source='https://www.iamsterdam.com/en/explore/winter-in-amsterdam/reasons-to-visit-amsterdam-in-winter'}
 if(c==='Interlaken'&&win){text='Keep your mountain day flexible and check local conditions before heading up. Save a relaxed lakeside or town day as an alternative.'}
 if(c==='Bali'){text='Balance a day of exploring with unhurried time near where you stay. Leave flexibility for outdoor plans and local conditions.'}
 if(length<=2)text+=' With '+length+(length===1?' day':' days')+', keep your shortlist small.';
 if((month===12&&Number(range.start.slice(8))>=20)||(month===1&&Number(range.start.slice(8))<=2))text+=' Check holiday opening hours before choosing your stops.';
 return `<aside class="planning-insight" aria-label="Date-based planning insight"><div class="insight-label"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg><b>AI insight</b><span>${parseDay(range.start).toLocaleDateString('en-GB',{month:'short'})}</span></div><p>${text}</p><small>Seasonal guidance${source?` · <a href="${source}" target="_blank" rel="noopener">City guide</a>`:''}</small></aside>`;
}
const activityPhotos={"Explore the Louvre": "louvre", "Visit the Musée d’Orsay": "orsay", "Discover the Musée de l’Orangerie": "orangerie", "Walk up to Sacré-Cœur": "sacre-coeur", "Wander Rue de l’Abreuvoir": "abreuvoir", "Visit the Musée Montmartre": "montmartre", "Explore Place du Tertre": "tertre", "Relax in Place des Vosges": "vosges", "Browse the Marais boutiques": "marais", "Explore Rue de Bretagne": "bretagne", "Lunch at Enfants Rouges": "market", "Browse Rue Montorgueil": "montorgueil", "Pick up a bakery breakfast": "bakery", "Try the stalls at Enfants Rouges": "market", "Plan a neighbourhood bistro dinner": "bistro"};
function cityArticle(c){
 const art=['Art & iconic sights','Make time for the places that tell the story of Paris, from celebrated collections to its unmistakable skyline.',['Explore the Louvre','Visit the Musée d’Orsay','See the Eiffel Tower','Discover the Musée de l’Orangerie']];
 const groups=c==='Paris'?[
 ['Art & iconic sights','Start with the Louvre’s Denon wing for celebrated masterpieces, spend another afternoon with the Impressionists at Orsay, or slow down in front of Monet’s Water Lilies at the Orangerie. Choose one museum at a time and leave room to linger.',['Explore the Louvre','Visit the Musée d’Orsay','Discover the Musée de l’Orangerie']],
 ['Montmartre, at your own pace','Head up to Sacré-Cœur for the view, then explore the smaller streets around the hill. The Musée Montmartre adds former artists’ studios and a garden to a neighbourhood walk.',['Walk up to Sacré-Cœur','Wander Rue de l’Abreuvoir','Visit the Musée Montmartre','Explore Place du Tertre']],
 ['An afternoon in the Marais','Start at Place des Vosges, browse the boutiques and historic streets, then follow Rue de Bretagne towards the Marché des Enfants Rouges. This is a neighbourhood to explore on foot, with plenty of reasons to pause.',['Relax in Place des Vosges','Browse the Marais boutiques','Explore Rue de Bretagne','Lunch at Enfants Rouges']],
 ['Eat your way around Paris','Make Rue Montorgueil your starting point for food shops, bakeries and café terraces. Pair a pastry stop with a market lunch, then leave an evening free for a bistro you discover along the way.',['Browse Rue Montorgueil','Pick up a bakery breakfast','Try the stalls at Enfants Rouges','Plan a neighbourhood bistro dinner']]
 ]:[['Discover '+c,'Explore the sights and everyday pleasures of the city.',cityIdeas[c]||['Explore the old town','Try the local food','Visit a local museum']]];
 return `<article class="city-article"><p class="guide-eyebrow">CITY GUIDE</p><h2>Things to do in ${c}</h2><p class="guide-intro">${c==='Paris'?'Art-filled afternoons, winding streets and something delicious around every corner. Find your kind of Paris, and add a few favourites to your itinerary.':c==='Amsterdam'?'Canals lined with narrow gabled houses, world-famous art and a city that moves by bicycle. Discover Rembrandt and Van Gogh, wander the Jordaan, and pause at a cosy brown café between waterside walks.':'Find your favourite experiences and add them to your itinerary.'}</p>${groups.map(([title,description,ideas])=>`<section class="guide-category"><h3>${title}</h3><p>${description}</p><div class="planning-suggestions">${ideas.map(a=>{const selected=(state.activities[c]||[]).includes(a);return `<button data-suggestion="${a}" aria-pressed="${selected}" class="planning-suggestion ${selected?'selected':''}"><img class="activity-thumbnail" src="${activityPhotos[a]?'assets/activities/'+activityPhotos[a]+'.jpg':newYearCities.find(x=>x[0]===c)?.[1]||'assets/paris-sunset.png'}" alt="" width="56" height="56" loading="lazy"><span class="activity-label">${a}</span><span class="suggestion-plus" aria-hidden="true">${selected?'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 4 4L19 6"/></svg>':'<img src="assets/figma/add.svg" width="18" height="18" alt="">'}</span><span class="sr-only">${selected?'Remove from itinerary':'Add to itinerary'}</span></button>`}).join('')}</div></section>`).join('')}${c==='Paris'?'<p class="guide-sources">Photos: <a href="activity-photo-credits.html" target="_blank" rel="noopener">credits</a><br>Explore more: <a href="https://parisjetaime.com/eng/article/montmartre-village-in-paris-a728" target="_blank" rel="noopener">Montmartre</a> · <a href="https://parisjetaime.com/eng/article/a-walk-in-the-marais-a838" target="_blank" rel="noopener">The Marais</a> · <a href="https://www.louvre.fr/en/explore/visitor-trails/the-louvre-s-masterpieces" target="_blank" rel="noopener">Louvre</a> · <a href="https://www.musee-orangerie.fr/en/node/33" target="_blank" rel="noopener">Orangerie</a></p>':''}</article>`;
}
document.addEventListener('click',e=>{
 const day=e.target.closest('[data-planning-day]')?.dataset.planningDay;if(!day)return;
 const c=state.cities[state.planningIndex||0];const r=state.cityDates[c];if(day<r.start||day>state.end)return;r.end=day;r.endChosen=day;
 const scroll=document.querySelector('#app').scrollTop;const left=document.querySelector('.city-date-row').scrollLeft;persist();render();document.querySelector('#app').scrollTop=scroll;document.querySelector('.city-date-row').scrollLeft=left;document.querySelector(`[data-planning-day="${day}"]`)?.focus({preventScroll:true});
});

render();

document.addEventListener("click",e=>{const b=e.target.closest("[data-planning-city]");if(b){transitionCity(Number(b.dataset.planningCity))}});


function routeVector(kind){
 const shape=kind==='up'?'M1 34L16 8H56':kind==='down'?'M1 8H41L56 34':'M1 8H30';
 const width=kind==='flat'?32:58;
 const dot=kind==='down'?1:kind==='flat'?30:56;
 return `<svg class="route-vector ${kind}" width="${width}" height="34" viewBox="0 0 ${width} 34" fill="none" aria-hidden="true"><path d="${shape}" pathLength="1" stroke="#1a1a1a" stroke-width="1"/><circle cx="${dot}" cy="8" r="2.5" fill="#1a1a1a"/></svg>`;
}
function planningRoute(index){
 let html='';for(let j=0;j<state.cities.length;j++){
 if(j===index){if(j>0)html+=routeVector('down');if(j<state.cities.length-1)html+=routeVector('up');continue}
 html+=`<button data-planning-city="${j}">${state.cities[j]}</button>`;
 if(j<state.cities.length-1&&j+1!==index)html+=routeVector('flat');
 }
 return `<nav class="figma-route morph-route" aria-label="Trip cities">${html}</nav>`;
}
let cityMotionFrame=0,cityTransitionBusy=false;
function motionText(node){if(!node)return null;const box=node.getBoundingClientRect(),style=getComputedStyle(node);return {text:node.textContent,box,fontSize:parseFloat(style.fontSize),fontFamily:style.fontFamily,fontWeight:style.fontWeight,lineHeight:style.lineHeight,color:style.color}}
function morphCityLabel(from,to){
 if(!from||!to)return Promise.resolve();const target=motionText(to);const ghost=document.createElement('span');ghost.textContent=from.text;
 Object.assign(ghost.style,{position:'fixed',left:from.box.left+'px',top:from.box.top+'px',fontFamily:from.fontFamily,fontSize:from.fontSize+'px',fontWeight:from.fontWeight,lineHeight:from.lineHeight,color:from.color,whiteSpace:'nowrap',pointerEvents:'none',zIndex:1000,transformOrigin:'top left'});
 document.body.appendChild(ghost);to.style.visibility='hidden';
 const animation=ghost.animate([{transform:'translate(0,0) scale(1)',color:from.color},{transform:`translate(${target.box.left-from.box.left}px,${target.box.top-from.box.top}px) scale(${target.fontSize/from.fontSize})`,color:target.color}],{duration:720,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
 return animation.finished.catch(()=>{}).finally(()=>{ghost.remove();to.style.visibility=''})
}
async function transitionCity(index){
 if(cityTransitionBusy||index===state.planningIndex||index<0||index>=state.cities.length)return;
 cityTransitionBusy=true;cancelAnimationFrame(cityMotionFrame);
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,previous=state.planningIndex||0;
 const app=document.querySelector('#app');if(app)app.scrollTop=0;
 const incoming=motionText(document.querySelector(`[data-planning-city="${index}"]`));
 const outgoing=motionText(document.querySelector('.planning-cover h1'));
 const retainedRail=document.querySelector('.city-date-row');const previousLeft=retainedRail?.scrollLeft||0;
 const departure=state.cityDates?.[state.cities[previous]]?.end;
 const positions=new Map([...document.querySelectorAll('[data-planning-city]')].map(n=>[n.dataset.planningCity,n.getBoundingClientRect()]));
 try{
 if(!reduced)await Promise.all([...document.querySelectorAll('.route-vector path')].map(n=>n.animate([{strokeDasharray:'1',strokeDashoffset:0},{strokeDasharray:'1',strokeDashoffset:1}],{duration:180,easing:'ease-in',fill:'forwards'}).finished));
 if(index===previous+1&&departure){const next=state.cityDates[state.cities[index]];next.start=departure;if(next.end&&next.end<departure){next.end='';next.endChosen=''}}
 state.planningIndex=index;persist();render();
 if(retainedRail){const fresh=document.querySelector('.city-date-row');const freshDays=[...fresh.children];fresh.replaceWith(retainedRail);retainedRail.scrollLeft=previousLeft;retainedRail.getBoundingClientRect();[...retainedRail.children].forEach((day,j)=>{const next=freshDays[j];if(!next)return;day.className=next.className;day.disabled=next.disabled;day.setAttribute('aria-pressed',next.getAttribute('aria-pressed'));day.setAttribute('aria-label',next.getAttribute('aria-label'))})}
 const rail=document.querySelector('.city-date-row'),arrival=rail?.querySelector('.arrival');
 if(rail){rail.scrollLeft=previousLeft;const target=Math.max(0,Math.min(rail.scrollWidth-rail.clientWidth,(arrival?.offsetLeft||0)-(rail.firstElementChild?.offsetLeft||0)));if(reduced)rail.scrollLeft=target;else{const began=performance.now(),from=rail.scrollLeft;const step=now=>{if(!rail.isConnected)return;const t=Math.max(0,Math.min(1,(now-began-140)/720));rail.scrollLeft=from+(target-from)*(1-Math.pow(1-t,3));if(t<1)cityMotionFrame=requestAnimationFrame(step)};cityMotionFrame=requestAnimationFrame(step)}}
 if(reduced)return;
 document.querySelectorAll('.route-vector path').forEach((n,j)=>n.animate([{strokeDasharray:'1',strokeDashoffset:1},{strokeDasharray:'1',strokeDashoffset:0}],{duration:550,delay:100+j*45,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'}));
 document.querySelectorAll('.route-vector circle').forEach(n=>n.animate([{opacity:0},{opacity:1}],{duration:300,delay:200,fill:'both'}));
 document.querySelectorAll('[data-planning-city]').forEach(n=>{const old=positions.get(n.dataset.planningCity);if(!old)return;const box=n.getBoundingClientRect();n.animate([{transform:`translateX(${old.left-box.left}px)`},{transform:'translateX(0)'}],{duration:720,easing:'cubic-bezier(.22,1,.36,1)'})});
 document.querySelector('.planning-cover>img')?.animate([{opacity:.3},{opacity:1}],{duration:650,easing:'ease-out'});
 await Promise.all([morphCityLabel(incoming,document.querySelector('.planning-cover h1')),morphCityLabel(outgoing,document.querySelector(`[data-planning-city="${previous}"]`))]);
 }finally{cityTransitionBusy=false}
}

function cityCoverPhoto(c){return c==='Paris'?'assets/figma/paris.png':newYearCities.find(x=>x[0]===c)?.[1]||'https://images.unsplash.com/photo-'+cityPhotos[c]+'?auto=format&fit=crop&w=800&h=480&q=85'}
function tripCityList(){return `<div class="content trip-city-list"><div class="figma-trip-heading"><h2>${state.title||'Your trip'}</h2><div class="trip-date-row"><p class="planning-trip-dates">${dateLabel(state.start)}${state.end?' – '+dateLabel(state.end):''}</p><button class="edit-trip-dates" data-go="dates" aria-label="Edit trip dates"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4Z"/></svg></button></div><button class="figma-close" data-go="home" aria-label="Close trip"><img src="assets/figma/close.svg" alt=""></button></div><div class="trip-list-label"><h3>Your cities</h3><span>${state.cities.length} stops</span></div><ol class="trip-city-cards">${state.cities.map((c,i)=>{const r=state.cityDates?.[c],count=(state.activities?.[c]||[]).length;return `<li><button class="trip-city-card" data-edit-city="${i}" aria-label="Open ${c}"><div class="trip-city-cover"><img src="${cityCoverPhoto(c)}" alt="" loading="${i?'lazy':'eager'}"><div class="trip-city-overlay"><h3>${c}</h3><p class="trip-cover-dates">${r?.start?dateLabel(r.start)+(r.end&&r.end!==r.start?' – '+dateLabel(r.end):''):'Choose city dates'}</p></div></div></button></li>`}).join('')}</ol><button class="linkbtn trip-edit-destinations" data-go="destinations">Edit destinations</button></div>`}

function homeTripCard(){
 if(!state.saved||!state.cities.length||!state.start||!state.end)return '';
 const city=state.cities[0],title=state.title||'Europe 2026';
 const photo=newYearCities.find(x=>x[0]===city)?.[1]||'https://images.unsplash.com/photo-'+cityPhotos[city]+'?auto=format&fit=crop&w=800&h=400&q=85';
 return `<section class="next-trip-section" aria-labelledby="next-trip-heading"><h3 id="next-trip-heading">Your next trip</h3><button class="next-trip-card" data-go="trip" aria-label="Open ${title}"><img src="${photo}" alt="${city}" width="700" height="300"><span class="next-trip-details"><strong>${title}</strong><span class="next-trip-dates">${dateLabel(state.start)} – ${dateLabel(state.end)}</span><span class="next-trip-route">${state.cities.join(' · ')}</span></span></button></section>`;
}
